/**
 * Cross-binding smoke: one prepared V2 plan, local and remote execution.
 *
 * The declared-schema bytes and plan bytes below are canonical fixtures
 * generated by the Rust contract crate; the Node side never builds or
 * mutates plans. Local execution runs through the native module against a
 * fresh isolated database; remote execution travels the versioned envelope
 * over HTTP to the `v2_smoke_server` example serving the same database,
 * and both paths must return byte-identical typed outcome JSON.
 */

import assert from "node:assert/strict";
import { spawn, type ChildProcess } from "node:child_process";
import { createRequire } from "node:module";
import net from "node:net";
import path from "node:path";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

import {
  TYPEDB_ADDRESS,
  TYPEDB_HTTP_PORT,
  TYPEDB_PASSWORD,
  TYPEDB_USERNAME,
} from "../common/index.ts";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const packageRoot = path.resolve(__dirname, "../../..");
const _require = createRequire(import.meta.url);
const pkg = _require(packageRoot) as typeof import("../../../typescript/index.ts");
const native = pkg.loadNative() as never as Record<string, CallableFunction>;

