const SCOPE = "binding-smoke";
const PROFILE = "typedb-3.12.1/v1";

function freePort(): Promise<number> {
  return new Promise((resolve, reject) => {
    const probe = net.createServer();
    probe.listen(0, "127.0.0.1", () => {
      const address = probe.address();
      if (address === null || typeof address === "string") {
        reject(new Error("no probe address"));
        return;
      }
      probe.close(() => resolve(address.port));
    });
  });
}

async function waitForPort(
  port: number,
  server: ChildProcess,
  timeoutMs: number,
): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (server.exitCode !== null) {
      throw new Error(`smoke server exited early with code ${server.exitCode}`);
    }
    const reachable = await new Promise<boolean>((resolve) => {
      const socket = net.connect({ host: "127.0.0.1", port, timeout: 1000 });
      socket.once("connect", () => {
        socket.destroy();
        resolve(true);
      });
      socket.once("error", () => resolve(false));
      socket.once("timeout", () => {
        socket.destroy();
        resolve(false);
      });
    });
    if (reachable) {
      return;
    }
    await new Promise((resolve) => setTimeout(resolve, 200));
  }
  throw new Error("smoke server never became reachable");
}

test("prepared plan executes locally and remotely", async () => {
  const database = `tb_v2_node_smoke_${process.pid}_${Date.now()}`;
  native.ensureRustDatabase(
    TYPEDB_ADDRESS,
    database,
    TYPEDB_USERNAME,
    TYPEDB_PASSWORD,
    TYPEDB_HTTP_PORT,
    null,
  );
  const db = native.connectRustDatabase(
    TYPEDB_ADDRESS,
    database,
    TYPEDB_USERNAME,
    TYPEDB_PASSWORD,
    TYPEDB_HTTP_PORT,
    null,
  ) as never as Record<string, CallableFunction>;
  try {
    const schemaTx = db.transaction("schema") as never as Record<
      string,
      CallableFunction
    >;
    schemaTx.queryJson(
      "define attribute smoke-name, value string; " +
        "entity smoke-person, owns smoke-name;",
    );
    schemaTx.commit();
    const writeTx = db.transaction("write") as never as Record<
      string,
      CallableFunction
    >;
    writeTx.queryJson(
      'insert $a isa smoke-person, has smoke-name "ada"; ' +
        '$b isa smoke-person, has smoke-name "bob";',
    );
    writeTx.commit();

    const declared = Buffer.from(DECLARED_B64, "base64");
    const plan = Buffer.from(PLAN_B64, "base64");
    const invocation = JSON.stringify({ operation: "rows", rows: [] });
    const authority = native.queryV2Authority(declared, SCOPE, PROFILE);
    const local = native.queryV2ExecuteLocal(
      db,
      authority,
      plan,
      invocation,
    ) as string;
    assert.ok(local.includes('"ada"'), local);
    assert.ok(local.includes('"bob"'), local);

    const port = await freePort();
    const server = spawn(
      "cargo",
      [
        "run",
        "--quiet",
        "-p",
        "type-bridge-server",
        "--features",
        "v2-query",
        "--example",
        "v2_smoke_server",
      ],
      {
        cwd: path.resolve(packageRoot, "../.."),
        env: {
          ...process.env,
          SMOKE_TYPEDB_ADDRESS: TYPEDB_ADDRESS,
          SMOKE_TYPEDB_USERNAME: TYPEDB_USERNAME,
          SMOKE_TYPEDB_PASSWORD: TYPEDB_PASSWORD,
          SMOKE_DATABASE: database,
          SMOKE_DECLARED_B64: DECLARED_B64,
          SMOKE_SCOPE: SCOPE,
          SMOKE_PROFILE: PROFILE,
          SMOKE_PORT: String(port),
        },
        stdio: "ignore",
      },
    );
    try {
      await waitForPort(port, server, 300_000);
      const nonce = `binding-smoke-node-${process.pid}-${Date.now()}`;
      const request = native.queryV2EncodeRemoteRequest(
        authority,
        plan,
        invocation,
        nonce,
        100,
        1 << 20,
        30_000,
      ) as Buffer;
      const response = await fetch(`http://127.0.0.1:${port}/v2/query`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: new Uint8Array(request),
      });
      const body = Buffer.from(await response.arrayBuffer());
      const remote = native.queryV2DecodeRemoteOutcome(
        authority,
        plan,
        invocation,
        body,
        nonce,
        100,
        1 << 20,
      ) as string;
      assert.equal(remote, local);
    } finally {
      server.kill("SIGKILL");
    }
  } finally {
    db.deleteDatabase();
  }
});
